using System;using System.IO;using System.Linq;using MET.Core;
class CityGovernanceProgram {
 static int count;static void Check(bool result,string name){if(!result)throw new Exception(name);Console.WriteLine("PASS "+name);count++;}
 static void Origin(CitySession s){var before=s.FocusedGame.snapshot();Check(s.FocusedGame.choose_origin(s.FocusedGame.s["origin_choices"][0].Text)=="","origin");s.AfterLocalCommand(before);}
 static void Main(string[] args){if(args.Length>1)Directory.CreateDirectory(args[1]);var c=new Catalog(args[0]);var session=new CitySession(c);session.New(42,1000);Check(session.Validate()=="","empty city semantic validation");Check(session.FocusedGame!=null,"nonnull bootstrap");Check(session.BeginDistrict(0,"agricultural")=="","first district");Origin(session);Check(session.Validate()=="","initial city semantic validation");string first=session.FocusedBlockId;var donor=session.FocusedGame;
 Check(session.BeginDistrict(1,"services")!="","unique active");Check(session.BeginBlock(1,"industrial",first)!="","insufficient real startup funds rejected");
 // Explicit bounded scenario fixture for branch/integrity checks, not a normal-play acceptance.
 donor.s["currency"]=1000;donor.s["projects"]["municipal"]["inventory"]=V.Map("food",50,"material",50,"goods",20);double money=donor.s["currency"].Double,food=donor.inventory_total("food"),material=donor.inventory_total("material");
 Check(session.BeginBlock(1,"industrial",first)=="","paid second block");string second=session.FocusedBlockId;Check(donor.s["currency"].Double==money-140&&donor.inventory_total("food")==food-12&&donor.inventory_total("material")==material-12,"startup deducts actual source once");Origin(session);Check(session.FocusedGame.s["currency"].Double==140&&session.FocusedGame.inventory_total("food")==12&&session.FocusedGame.inventory_total("material")==12,"origin cannot restore initial free cash or stock");var state=session.snapshot();session.AfterLocalCommand(session.FocusedGame.snapshot());Check(session.FocusedGame.s["currency"]==140,"startup receipt not repeated");
 Check(session.Validate()=="","two-block city validation");Check(CitySession.ValidateEnvelope(c,state)=="","detached envelope validation");Check(!session.Block(first).Has("state"),"runtime metadata has no stale state");var old=donor.s;donor.s=donor.snapshot();donor.s["currency"]=777;Check(session.snapshot()["blocks"][first]["state"]["currency"]==777,"snapshot takes replaced latest Game.s");var viewBefore=session.snapshot();session.FocusBlock(first);session.FocusBlock(second);Check(session.snapshot()==viewBefore,"focus round trip changes no simulation");
 var detached=session.snapshot();double liveCash=donor.s["currency"].Double;string liveSpecialization=session.Block(first)["specialization"].Text;detached["blocks"][first]["state"]["currency"]=-123;detached["blocks"][first]["specialization"]="detached-only";Check(donor.s["currency"].Double==liveCash&&session.Block(first)["specialization"].Text==liveSpecialization,"snapshot nested mutation leaves live state and metadata unchanged");
 Check(Bonus.grant(donor,"P07","fixture:portable")=="","fixture license");Check(session.TransferPortable(first,"P07",second)=="","portable consumes actual unused license");Check(donor.s["block"]["bonus_wallet"]["P07"]["charges"]==0&&session.FocusedGame.s["block"]["bonus_wallet"]["P07"]["charges"]==1,"one transferred license");Check(session.TransferPortable(first,"P07",second)!="","cannot transfer consumed license again");Check(Bonus.grant(donor,"B01","fixture:local")=="","fixture Local license");Check(session.TransferPortable(first,"B01",second)!="","Local stays in source");
 session.CaptureHistory();int events=session.s["history"].Count;session.CaptureHistory();Check(session.s["history"].Count==events,"history capture idempotent");session.s["snapshot_extension_fixture"]=V.Map("nested",V.Arr(17,V.Map("name","city")));session.Block(first)["snapshot_extension_fixture"]=V.Map("nested",V.Arr(23,V.Map("name","block")));string encoded=Store.encode(session.snapshot());var decoded=CityStore.decode(c,encoded);Check(decoded["ok"].Bool,"whole city roundtrip");var loaded=new CitySession(c);Check(loaded.Restore(decoded["state"])=="","restore exact owner graph");loaded.CaptureHistory();Check(loaded.s["history"].Count==events,"reload history not replayed");Check(loaded.FocusedGame.s["rng"]==session.FocusedGame.s["rng"],"RNG preserved");
 var metadataPreserved=decoded["state"].Pairs.Where(p=>p.Key!="blocks").All(p=>loaded.s[p.Key]==p.Value)&&decoded["state"]["blocks"].Pairs.All(b=>b.Value.Pairs.Where(p=>p.Key!="state").All(p=>loaded.Block(b.Key)[p.Key]==p.Value)&&!loaded.Block(b.Key).Has("state"));Check(metadataPreserved,"restore preserves every city and block metadata field without local state");double loadedCash=loaded.Games[first].s["currency"].Double;string loadedSpec=loaded.Block(first)["specialization"].Text;decoded["state"]["blocks"][first]["state"]["currency"]=-321;decoded["state"]["blocks"][first]["specialization"]="source-only";Check(loaded.Games[first].s["currency"].Double==loadedCash&&loaded.Block(first)["specialization"].Text==loadedSpec,"restored local state and metadata detach from source envelope");
 var corrupt=session.snapshot();corrupt["districts"][session.ActiveDistrictId]["block_ids"].Add(first);Check(!CityStore.decode(c,Store.encode(corrupt))["ok"].Bool,"duplicate block ownership rejected");corrupt=session.snapshot();corrupt["blocks"][first]["state"]["projects"]["municipal"]["inventory"]["food"]=-1;Check(!CityStore.decode(c,Store.encode(corrupt))["ok"].Bool,"bad actual local inventory rejected");
 string path=Path.Combine(args.Length>1?args[1]:Path.GetTempPath(),"met-governance-test-city.json");Check(CityStore.write(session,path)=="","semantic city save");Check(CityStore.write(session,path)=="","semantic backup save");File.WriteAllText(path,Store.encode(corrupt));var recovered=CityStore.read(c,path);Check(recovered["ok"].Bool&&recovered["from_backup"].Bool,"semantic corrupt main falls back to valid backup");var beforeResume=loaded.snapshot();double dt=loaded.FocusedGame.s["dt"].Double;loaded.Resume(4600);Check(loaded.s["external_seconds"]==beforeResume["external_seconds"]&&loaded.FocusedGame.s["dt"].Double==dt&&loaded.s["offline_seconds"]==3600,"resume records offline only");
 // Actual shortage readings, with fixture supplies exhausted, cause retirement; stored assets survive.
 var d=loaded.District(loaded.ActiveDistrictId);string did=loaded.ActiveDistrictId;foreach(var g in loaded.Games.Values){foreach(var group in g.s["groups"].Values)group["living"]=V.Map("food",0,"medical",0,"commercial",0,"education",0);g.s["currency"]=-10;}
 loaded.GovernanceTick(V.From(loaded.Games.Keys.ToDictionary(x=>x,x=>6.0)),0);Check(loaded.ActiveDistrictId==""&&d["status"]=="autonomous"&&d["run_history"].Count==1&&d["crisis"]["active"].Bool,"actual shortage and bankruptcy retire district");Check(loaded.Games.Count==2,"crisis preserves old entities and games");loaded.Games[first].s["currency"]=500;Check(loaded.ReturnDistrict(did)=="","paid return");Check(loaded.Games[first].s["currency"]==410&&d["term"]==2&&loaded.ActiveDistrictId==did,"return costs money and opens new term");Check(loaded.Validate()=="","governance history semantic roundtrip");Console.WriteLine("GOVERNANCE CHECKS "+count+" PASS; fixture scenarios, not no-injection full arc");}
}
